1	import { NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { jsonError } from "@/lib/tools/api";
4	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
5	import { aiAvailable, aiCandidates } from "@/lib/tools/domain-ai";
6	import { checkAvailabilityBatched, type DomainResult } from "@/lib/tools/domain-availability";
7	import { generateCandidates, type Candidate } from "@/lib/tools/domain-generate";
8	import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";
9	
10	export const runtime = "nodejs";
11	export const dynamic = "force-dynamic";
12	
13	/**
14	 * AI domain-name generator — public, unauthenticated, and therefore capped hard.
15	 *
16	 * Cost controls, in order of defence:
17	 *   1. Two per-IP sliding windows (burst + hourly) via the shared tool limiter.
18	 *   2. MAX_NAMES caps how many labels we generate, so at most ONE Claude call
19	 *      with a fixed `max_tokens` per accepted request.
20	 *   3. MAX_LOOKUPS caps registrar volume per request; the lookups are batched
21	 *      into a single upstream call and cached for 10 minutes, and a process-wide
22	 *      window in `domain-availability.ts` guards the shared registrar budget.
23	 *
24	 * Degradation: no ANTHROPIC_API_KEY (or any Claude failure) falls back to the
25	 * local heuristic generator; a registrar failure marks names "unknown" rather
26	 * than claiming they're free. Neither is surfaced to the visitor as an error.
27	 */
28	
29	/** Distinct name ideas per request. */
30	const MAX_NAMES = 12;
31	
32	/** Absolute ceiling on registrar lookups per request (names x TLDs). */
33	const MAX_LOOKUPS = 24;
34	
35	/** TLDs a visitor may select at once. */
36	const MAX_TLDS = 3;
37	
38	const MAX_IDEA_LEN = 400;
39	const MAX_KEYWORDS_LEN = 120;
40	
41	const VALID_TONES = new Set(TONES.map((t) => t.value));
42	
43	type Body = { idea?: unknown; keywords?: unknown; tone?: unknown; tlds?: unknown };
44	
45	function readString(v: unknown, max: number): string {
46	  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
47	}
48	
49	function readTlds(v: unknown): string[] {
50	  if (!Array.isArray(v)) return DEFAULT_TLDS;
51	  const out: string[] = [];
52	  for (const raw of v) {
53	    if (typeof raw !== "string") continue;
54	    const tld = raw.toLowerCase().replace(/^\./, "").trim();
55	    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
56	    if (out.length >= MAX_TLDS) break;
57	  }
58	  return out.length ? out : DEFAULT_TLDS;
59	}
60	
61	/**
62	 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
63	 * visitor's first-choice extension is checked for every name before we spend any
64	 * budget on the second choice.
65	 */
66	function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
67	  const domains: string[] = [];
68	  for (const tld of tlds) {
69	    for (const c of candidates) {
70	      if (domains.length >= MAX_LOOKUPS) return domains;
71	      domains.push(`${c.sld}.${tld}`);
72	    }
73	  }
74	  return domains;
75	}
76	
77	export async function POST(req: Request) {
78	  // Burst limit, then a longer window so a single IP can't grind all day.
79	  const burst = toolRateLimitByIp(req, "domain-generator", { max: 6, windowMs: 60_000 });
80	  if (burst) return burst;
81	  const hourly = toolRateLimitByIp(req, "domain-generator-hourly", { max: 40, windowMs: 60 * 60_000 });
82	  if (hourly) return hourly;
83	
84	  const body = (await req.json().catch(() => ({}))) as Body;
85	  const idea = readString(body.idea, MAX_IDEA_LEN);
86	  const keywords = readString(body.keywords, MAX_KEYWORDS_LEN);
87	  const toneRaw = readString(body.tone, 20);
88	  const tone: Tone = VALID_TONES.has(toneRaw as Tone) ? (toneRaw as Tone) : "any";
89	  const tlds = readTlds(body.tlds);
90	
91	  if (idea.length < 8) {
92	    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
93	  }
94	
95	  // 1) Names — Claude when the platform key is set, heuristics otherwise.
96	  let candidates: Candidate[] | null = null;
97	  let source: "ai" | "heuristic" = "heuristic";
98	  if (aiAvailable()) {
99	    candidates = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
100	    if (candidates && candidates.length) source = "ai";
101	  }
102	  if (!candidates || candidates.length < MAX_NAMES) {
103	    const local = generateCandidates({ idea, keywords, tone, limit: MAX_NAMES });
104	    const merged = candidates ? [...candidates] : [];
105	    const seen = new Set(merged.map((c) => c.sld));
106	    for (const c of local) {
107	      if (merged.length >= MAX_NAMES) break;
108	      if (seen.has(c.sld)) continue;
109	      seen.add(c.sld);
110	      merged.push(c);
111	    }
112	    candidates = merged;
113	  }
114	
115	  if (!candidates.length) {
116	    return jsonError("We couldn't build names from that description — try adding a little more detail.");
117	  }
118	
119	  const byLabel = new Map(candidates.map((c) => [c.sld, c]));
120	
121	  // 2) Availability — one batched, cached registrar call.
122	  const domains = buildDomains(candidates, tlds);
123	  const availability = await checkAvailabilityBatched(domains);
124	
125	  const results = availability.results.map((r: DomainResult) => {
126	    const sld = r.domain.slice(0, r.domain.lastIndexOf("."));
127	    const tld = r.domain.slice(r.domain.lastIndexOf(".") + 1);
128	    const meta = byLabel.get(sld);
129	    return {
130	      domain: r.domain,
131	      sld,
132	      tld,
133	      status: r.status,
134	      premium: r.premium,
135	      priceCents: r.priceCents,
136	      renewCents: r.renewCents,
137	      style: meta?.style ?? "invented",
138	      note: meta?.note ?? "",
139	    };
140	  });
141	
142	  // Available first (cheapest first within that), then unknown, then taken.
143	  const rank = { available: 0, unknown: 1, taken: 2 } as const;
144	  results.sort(
145	    (a, b) =>
146	      rank[a.status] - rank[b.status] ||
147	      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
148	      a.domain.length - b.domain.length,
149	  );
150	
151	  // Signed-in visitors go straight into the pre-filled registration wizard;
152	  // everyone else lands on signup with the name carried through.
153	  let signedIn = false;
154	  try {
155	    signedIn = Boolean(await currentUser());
156	  } catch {
157	    /* session lookup unavailable — treat as anonymous */
158	  }
159	
160	  return NextResponse.json({
161	    ok: true,
162	    source,
163	    signedIn,
164	    registrarConfigured: availability.configured,
165	    throttled: availability.throttled,
166	    checked: results.length,
167	    tlds,
168	    results,
169	  });
170	}
