1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useRef, useState } from "react";
5	import { IconArrow, IconCheck } from "../icons";
6	import { CopyButton, ErrorNote, Field, RunButton } from "./ui";
7	import { DEFAULT_TLDS, SUGGESTABLE_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";
8	
9	/**
10	 * Interactive island for /tools/domain-name-generator.
11	 *
12	 * Honesty rules baked into the UI:
13	 *  - Prices are only rendered when the registrar actually returned one.
14	 *  - "Available" is always framed as available *right now, at the registrar*;
15	 *    the registration flow is the source of truth at checkout.
16	 *  - When the registrar can't be reached, names are marked "not checked" rather
17	 *    than being presented as free.
18	 */
19	
20	type Status = "available" | "taken" | "unknown";
21	
22	type Result = {
23	  domain: string;
24	  sld: string;
25	  tld: string;
26	  status: Status;
27	  premium: boolean;
28	  priceCents: number | null;
29	  renewCents: number | null;
30	  style: string;
31	  note: string;
32	};
33	
34	type ApiResponse = {
35	  ok: true;
36	  source: "ai" | "heuristic";
37	  signedIn: boolean;
38	  registrarConfigured: boolean;
39	  throttled: boolean;
40	  checked: number;
41	  tlds: string[];
42	  results: Result[];
43	};
44	
45	const MAX_TLDS = 3;
46	const MAX_IDEA = 400;
47	
48	const STYLE_LABEL: Record<string, string> = {
49	  compound: "Compound",
50	  invented: "Invented",
51	  "real-word": "Real word",
52	  playful: "Playful",
53	  descriptive: "Descriptive",
54	};
55	
56	function money(cents: number | null): string | null {
57	  if (cents === null) return null;
58	  return `$${(cents / 100).toFixed(2)}`;
59	}
60	
61	const LOADING_STEPS = [
62	  "Reading your brief…",
63	  "Shaping name candidates…",
64	  "Checking live availability at the registrar…",
65	  "Pricing what's still free…",
66	];
67	
68	export function DomainGeneratorTool({ presetIdea = "", presetTone }: { presetIdea?: string; presetTone?: Tone }) {
69	  const [idea, setIdea] = useState(presetIdea);
70	  const [keywords, setKeywords] = useState("");
71	  const [tone, setTone] = useState<Tone>(presetTone ?? "any");
72	  const [tlds, setTlds] = useState<string[]>(DEFAULT_TLDS);
73	  const [loading, setLoading] = useState(false);
74	  const [step, setStep] = useState(0);
75	  const [error, setError] = useState("");
76	  const [data, setData] = useState<ApiResponse | null>(null);
77	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
78	
79	  useEffect(() => () => timers.current.forEach(clearTimeout), []);
80	
81	  function toggleTld(tld: string) {
82	    setTlds((prev) => {
83	      if (prev.includes(tld)) return prev.length === 1 ? prev : prev.filter((t) => t !== tld);
84	      if (prev.length >= MAX_TLDS) return prev;
85	      return [...prev, tld];
86	    });
87	  }
88	
89	  async function run(e?: React.SyntheticEvent) {
90	    e?.preventDefault();
91	    if (idea.trim().length < 8 || loading) return;
92	    setLoading(true);
93	    setError("");
94	    setData(null);
95	    setStep(0);
96	    timers.current.forEach(clearTimeout);
97	    timers.current = LOADING_STEPS.slice(1).map((_, i) =>
98	      setTimeout(() => setStep(i + 1), 900 * (i + 1)),
99	    );
100	
101	    try {
102	      const res = await fetch("/api/tools/domain-generator", {
103	        method: "POST",
104	        headers: { "content-type": "application/json" },
105	        body: JSON.stringify({ idea, keywords, tone, tlds }),
106	      });
107	      const json = await res.json();
108	      if (!res.ok || !json.ok) throw new Error(json.error || "We couldn't generate names just now.");
109	      setData(json as ApiResponse);
110	    } catch (err) {
111	      setError(err instanceof Error ? err.message : "We couldn't generate names just now.");
112	    } finally {
113	      timers.current.forEach(clearTimeout);
114	      setLoading(false);
115	    }
116	  }
117	
118	  const available = data?.results.filter((r) => r.status === "available") ?? [];
119	  const unchecked = data?.results.filter((r) => r.status === "unknown") ?? [];
120	  const taken = data?.results.filter((r) => r.status === "taken") ?? [];
121	
122	  const registerHref = (domain: string) =>
123	    data?.signedIn
124	      ? `/dashboard/domains/register?domain=${encodeURIComponent(domain)}`
125	      : `/register?domain=${encodeURIComponent(domain)}`;
126	
127	  return (
128	    <div className="space-y-6">
129	      <style>{`
130	        .nx-name-row { animation: nx-name-in .32s cubic-bezier(.22,1,.36,1) both; }
131	        @keyframes nx-name-in { from { opacity:0; transform: translateY(6px);} to { opacity:1; transform:none;} }
132	        .nx-skel { animation: nx-skel 1.2s ease-in-out infinite; }
133	        @keyframes nx-skel { 0%,100%{opacity:.35} 50%{opacity:.7} }
134	        @media (prefers-reduced-motion: reduce) { .nx-name-row, .nx-skel { animation: none !important; } }
135	      `}</style>
136	
137	      <form onSubmit={run} className="space-y-5">
138	        <Field
139	          label="What are you building?"
140	          hint="A sentence or two is plenty. The more specific, the better the names."
141	        >
142	          <textarea
143	            className="input min-h-[92px] resize-y leading-relaxed"
144	            placeholder="A subscription coffee roastery shipping single-origin beans to offices in Manchester"
145	            value={idea}
146	            maxLength={MAX_IDEA}
147	            onChange={(e) => setIdea(e.target.value)}
148	            spellCheck={false}
149	          />
150	        </Field>
151	
152	        <div className="grid gap-4 sm:grid-cols-2">
153	          <Field label="Words to work in (optional)" hint="Comma separated. We'll treat them as hints, not rules.">
154	            <input
155	              className="input"
156	              placeholder="roast, office, origin"
157	              value={keywords}
158	              maxLength={120}
159	              onChange={(e) => setKeywords(e.target.value)}
160	              autoCapitalize="none"
161	              spellCheck={false}
162	            />
163	          </Field>
164	          <Field label="Naming style" hint={TONES.find((t) => t.value === tone)?.hint}>
165	            <select className="input" value={tone} onChange={(e) => setTone(e.target.value as Tone)}>
166	              {TONES.map((t) => (
167	                <option key={t.value} value={t.value}>
168	                  {t.label}
169	                </option>
170	              ))}
171	            </select>
172	          </Field>
173	        </div>
174	
175	        <div>
176	          <span className="label">Extensions to check (up to {MAX_TLDS})</span>
177	          <div className="flex flex-wrap gap-2">
178	            {SUGGESTABLE_TLDS.map((t) => {
179	              const on = tlds.includes(t.tld);
180	              return (
181	                <button
182	                  key={t.tld}
183	                  type="button"
184	                  onClick={() => toggleTld(t.tld)}
185	                  title={t.note}
186	                  aria-pressed={on}
187	                  className={`rounded-lg border px-3 py-1.5 font-mono text-sm transition-colors ${
188	                    on
189	                      ? "border-brand-500/50 bg-brand-500/15 text-brand-200"
190	                      : "border-white/[0.08] bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-slate-200"
191	                  }`}
192	                >
193	                  {t.label}
194	                </button>
195	              );
196	            })}
197	          </div>
198	          <p className="mt-2 text-xs text-slate-500">
199	            We check your first extension across every name before spending checks on the next one.
200	          </p>
201	        </div>
202	
203	        <div className="flex flex-wrap items-center gap-3">
204	          <RunButton loading={loading} type="submit" disabled={idea.trim().length < 8}>
205	            Generate names
206	          </RunButton>
207	          <span className="text-xs text-slate-500">Free, no account needed. Live availability from our registrar.</span>
208	        </div>
209	      </form>
210	
211	      <ErrorNote>{error}</ErrorNote>
212	
213	      {loading && (
214	        <div className="rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
215	          <p className="flex items-center gap-2 text-sm text-slate-300">
216	            <span className="nx-skel h-2 w-2 rounded-full bg-brand-400" />
217	            {LOADING_STEPS[Math.min(step, LOADING_STEPS.length - 1)]}
218	          </p>
219	          <div className="mt-4 space-y-2">
220	            {Array.from({ length: 5 }).map((_, i) => (
221	              <div
222	                key={i}
223	                className="nx-skel h-11 rounded-xl border border-white/[0.05] bg-white/[0.03]"
224	                style={{ animationDelay: `${i * 120}ms` }}
225	              />
226	            ))}
227	          </div>
228	        </div>
229	      )}
230	
231	      {data && !loading && (
232	        <div className="space-y-6">
233	          {!data.registrarConfigured && (
234	            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
235	              <b>Live availability is temporarily unavailable.</b> These are still real name ideas — check each one
236	              before you commit.
237	            </div>
238	          )}
239	          {data.registrarConfigured && data.throttled && (
240	            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
241	              We're checking a lot of names right now, so some below weren't verified. Try again in a minute for the
242	              rest.
243	            </div>
244	          )}
245	
246	          {available.length > 0 && (
247	            <section>
248	              <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
249	                <h3 className="text-base font-semibold text-white">
250	                  Available right now{" "}
251	                  <span className="text-sm font-normal text-slate-500">({available.length})</span>
252	                </h3>
253	                <p className="text-xs text-slate-500">Price shown is the first year, from our registrar.</p>
254	              </div>
255	              <ul className="space-y-2">
256	                {available.map((r, i) => (
257	                  <li
258	                    key={r.domain}
259	                    className="nx-name-row rounded-xl border border-emerald-500/20 bg-emerald-500/[0.04] p-3 transition-colors hover:border-emerald-400/40 sm:p-4"
260	                    style={{ animationDelay: `${Math.min(i, 8) * 40}ms` }}
261	                  >
262	                    <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
263	                      <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
264	                        <IconCheck size={13} />
265	                      </span>
266	                      <span className="min-w-0 break-all font-mono text-[15px] font-semibold text-white">
267	                        {r.domain}
268	                      </span>
269	                      {r.premium && (
270	                        <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
271	                          Premium
272	                        </span>
273	                      )}
274	                      <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-slate-400">
275	                        {STYLE_LABEL[r.style] ?? r.style}
276	                      </span>
277	
278	                      <span className="ml-auto flex flex-wrap items-center gap-2 sm:gap-3">
279	                        {money(r.priceCents) && (
280	                          <span className="text-right text-sm">
281	                            <span className="font-semibold text-white">{money(r.priceCents)}</span>
282	                            <span className="text-slate-500">/yr</span>
283	                          </span>
284	                        )}
285	                        <CopyButton value={r.domain} label="Copy" />
286	                        <Link href={registerHref(r.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
287	                          Register
288	                          <IconArrow size={13} />
289	                        </Link>
290	                      </span>
291	                    </div>
292	                    {(r.note || money(r.renewCents)) && (
293	                      <p className="mt-2 pl-9 text-xs leading-relaxed text-slate-500">
294	                        {r.note}
295	                        {r.note && money(r.renewCents) ? " · " : ""}
296	                        {money(r.renewCents) ? `Renews at ${money(r.renewCents)}/yr` : ""}
297	                      </p>
298	                    )}
299	                  </li>
300	                ))}
301	              </ul>
302	              <p className="mt-3 text-xs leading-relaxed text-slate-500">
303	                Availability comes straight from our registrar and can change minute to minute — someone else may
304	                register a name while you're deciding. Your registration checkout re-checks the name and its exact price
305	                before you pay.
306	              </p>
307	            </section>
308	          )}
309	
310	          {available.length === 0 && (
311	            <div className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-300">
312	              Every name we tried is already taken. That usually means the words are too obvious — try a more specific
313	              description, switch the style to <b>Invented &amp; brandable</b>, or add <span className="font-mono">.io</span>{" "}
314	              or <span className="font-mono">.co</span> to the extensions.
315	            </div>
316	          )}
317	
318	          {unchecked.length > 0 && (
319	            <section>
320	              <h3 className="mb-3 text-base font-semibold text-white">
321	                Not checked <span className="text-sm font-normal text-slate-500">({unchecked.length})</span>
322	              </h3>
323	              <ul className="flex flex-wrap gap-2">
324	                {unchecked.map((r) => (
325	                  <li
326	                    key={r.domain}
327	                    className="rounded-lg border border-white/[0.07] bg-navy-900/50 px-3 py-1.5 font-mono text-sm text-slate-300"
328	                  >
329	                    {r.domain}
330	                  </li>
331	                ))}
332	              </ul>
333	              <p className="mt-2 text-xs text-slate-500">
334	                We couldn't get an answer from the registrar for these. They may or may not be free.
335	              </p>
336	            </section>
337	          )}
338	
339	          {taken.length > 0 && (
340	            <section>
341	              <h3 className="mb-3 text-base font-semibold text-slate-400">
342	                Already taken <span className="text-sm font-normal text-slate-600">({taken.length})</span>
343	              </h3>
344	              <ul className="flex flex-wrap gap-2">
345	                {taken.map((r) => (
346	                  <li
347	                    key={r.domain}
348	                    className="rounded-lg border border-white/[0.05] bg-white/[0.02] px-3 py-1.5 font-mono text-sm text-slate-600 line-through decoration-slate-700"
349	                  >
350	                    {r.domain}
351	                  </li>
352	                ))}
353	              </ul>
354	              <p className="mt-2 text-xs text-slate-600">
355	                Taken names sometimes free up.{" "}
356	                <Link href="/tools/whois" className="text-brand-400 hover:text-brand-300">
357	                  Run a WHOIS lookup
358	                </Link>{" "}
359	                to see when one expires.
360	              </p>
361	            </section>
362	          )}
363	
364	          <div className="flex flex-wrap items-center gap-3 border-t border-white/[0.06] pt-4">
365	            <RunButton loading={false} type="button" onClick={() => void run()}>
366	              Generate another set
367	            </RunButton>
368	            <Link href="/domains" className="btn-secondary px-4 py-2 text-sm">
369	              Search an exact name
370	            </Link>
371	          </div>
372	        </div>
373	      )}
374	    </div>
375	  );
376	}
