1	/**
2	 * Claude-powered name generation for the public domain-name generator.
3	 *
4	 * Why this doesn't call `askClaude` from `lib/anthropic.ts`: that helper is the
5	 * BYOK path for the "Build with Claude" feature and hard-codes an Opus model.
6	 * This is a free, unauthenticated, high-volume SEO tool, so it needs the
7	 * cheapest capable model instead. We reuse `platformKeyConfigured()` from that
8	 * module for the key check and keep the same dependency-free plain-fetch style.
9	 *
10	 * Cost posture: Haiku, a compact system prompt, a hard `max_tokens` ceiling, one
11	 * request per (rate-limited) visitor request, and a short timeout. If anything
12	 * at all goes wrong we return null and the caller falls back to the local
13	 * heuristic generator — visitors never see an AI error.
14	 */
15	
16	import { platformKeyConfigured } from "@/lib/anthropic";
17	import { normalizeSld, type Candidate, type NameStyle } from "./domain-generate";
18	import type { Tone } from "./domain-vocab";
19	
20	const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
21	
22	/** Cheapest capable model. Do not upgrade this without an owner cost decision. */
23	const MODEL = "claude-haiku-4-5-20251001";
24	
25	const MAX_TOKENS = 1200;
26	const TIMEOUT_MS = 20_000;
27	
28	/** True when the owner has set ANTHROPIC_API_KEY and the AI path can run. */
29	export function aiAvailable(): boolean {
30	  return platformKeyConfigured();
31	}
32	
33	const SYSTEM = `You are a senior brand naming consultant. You name companies for a living.
34	
35	Given a business description, invent domain-name candidates: the second-level label only (no dot, no TLD).
36	
37	Hard rules:
38	- lowercase a-z and digits only; never hyphens, spaces, or punctuation
39	- 4 to 14 characters; shorter is better
40	- must be pronounceable out loud on the first try by an English speaker
41	- must be spellable after hearing it once
42	- no numbers substituting for words (no "4u", "2go"), no misspelled-brand cliches
43	- never just <keyword>+<generic suffix> for every entry; earn each name
44	- avoid names that read as an existing famous brand
45	
46	Aim for a genuine spread of styles:
47	- compound: two real words fused (e.g. "northbeam", "saltmarket")
48	- invented: a coined word or portmanteau with no prior meaning (e.g. "verolo", "cadenza")
49	- real-word: a single evocative existing word used as a brand (e.g. "thistle", "keystone")
50	- playful: warm, human, a little unexpected (e.g. "buttermade", "gladhand")
51	- descriptive: literal and searchable, when that serves the business (e.g. "roastanddeliver")
52	
53	Return ONLY a JSON array, no prose, no markdown fence:
54	[{"name":"northbeam","style":"compound","why":"Solid and structural; suits a construction brand."}]
55	
56	"why" is at most 12 words and explains the naming choice, not the business.`;
57	
58	type AiRow = { name?: unknown; style?: unknown; why?: unknown };
59	
60	const STYLES: NameStyle[] = ["compound", "invented", "real-word", "playful", "descriptive"];
61	
62	function coerceStyle(v: unknown): NameStyle {
63	  const s = String(v ?? "").toLowerCase().replace(/[\s_]+/g, "-");
64	  return (STYLES as string[]).includes(s) ? (s as NameStyle) : "invented";
65	}
66	
67	/** Pull the first JSON array out of a model reply, tolerating stray prose/fences. */
68	function extractJsonArray(text: string): unknown[] | null {
69	  const start = text.indexOf("[");
70	  const end = text.lastIndexOf("]");
71	  if (start === -1 || end <= start) return null;
72	  try {
73	    const parsed = JSON.parse(text.slice(start, end + 1));
74	    return Array.isArray(parsed) ? parsed : null;
75	  } catch {
76	    return null;
77	  }
78	}
79	
80	const TONE_BRIEF: Record<Tone, string> = {
81	  any: "Mix every style roughly evenly.",
82	  modern: "Lean modern and short: clipped, punchy, one or two syllables.",
83	  invented: "Lean invented: coined words and portmanteaus with no prior meaning.",
84	  playful: "Lean playful: warm, human, a little unexpected — but still credible.",
85	  professional: "Lean professional: credible for finance, law, healthcare and B2B buyers.",
86	  descriptive: "Lean descriptive: literal names a customer would search for.",
87	};
88	
89	/**
90	 * Ask Claude for `count` candidate labels. Returns null on missing key, HTTP
91	 * error, timeout, or unparseable output — the caller must have a fallback.
92	 */
93	export async function aiCandidates(opts: {
94	  idea: string;
95	  keywords?: string;
96	  tone: Tone;
97	  count: number;
98	}): Promise<Candidate[] | null> {
99	  const apiKey = process.env.ANTHROPIC_API_KEY?.trim();
100	  if (!apiKey) return null;
101	
102	  const parts = [
103	    `Business description: ${opts.idea}`,
104	    opts.keywords ? `Words the owner would like worked in (optional, not mandatory): ${opts.keywords}` : "",
105	    TONE_BRIEF[opts.tone] ?? TONE_BRIEF.any,
106	    `Return exactly ${opts.count} candidates as the JSON array described above.`,
107	  ].filter(Boolean);
108	
109	  const controller = new AbortController();
110	  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
111	  let res: Response;
112	  try {
113	    res = await fetch(ANTHROPIC_URL, {
114	      method: "POST",
115	      headers: {
116	        "content-type": "application/json",
117	        "x-api-key": apiKey,
118	        "anthropic-version": "2023-06-01",
119	      },
120	      body: JSON.stringify({
121	        model: MODEL,
122	        max_tokens: MAX_TOKENS,
123	        system: SYSTEM,
124	        messages: [{ role: "user", content: parts.join("\n\n") }],
125	      }),
126	      signal: controller.signal,
127	    });
128	  } catch {
129	    return null; // network error or timeout
130	  } finally {
131	    clearTimeout(timer);
132	  }
133	
134	  if (!res.ok) return null;
135	
136	  let text: string;
137	  try {
138	    const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
139	    text = (data.content ?? [])
140	      .filter((b) => b.type === "text" && typeof b.text === "string")
141	      .map((b) => b.text as string)
142	      .join("")
143	      .trim();
144	  } catch {
145	    return null;
146	  }
147	
148	  const rows = extractJsonArray(text);
149	  if (!rows) return null;
150	
151	  const out: Candidate[] = [];
152	  const seen = new Set<string>();
153	  for (const row of rows) {
154	    if (!row || typeof row !== "object") continue;
155	    const r = row as AiRow;
156	    const sld = normalizeSld(String(r.name ?? ""));
157	    if (!sld || seen.has(sld)) continue;
158	    seen.add(sld);
159	    const why = typeof r.why === "string" ? r.why.trim().slice(0, 90) : "";
160	    out.push({ sld, style: coerceStyle(r.style), note: why });
161	    if (out.length >= opts.count) break;
162	  }
163	  return out.length ? out : null;
164	}
