7	 * candidate for length, pronounceability and keyword relevance, then keeps the
8	 * best spread of styles. The output is a list of bare second-level labels — the
9	 * caller pairs them with TLDs and checks availability.
10	 *
11	 * Pure functions, no I/O, deterministic apart from an explicitly seeded RNG so
12	 * two visitors with the same brief don't get an identical page.
13	 */
14	
15	import {
16	  BRAND_PREFIXES,
17	  BRAND_SUFFIXES,
18	  COINED_ROOTS,
19	  STANDALONE_WORDS,
