27	export type Candidate = {
28	  /** Bare second-level label, lowercase a-z0-9 only. */
29	  sld: string;
30	  style: NameStyle;
31	  /** One short line on why it works. Shown as muted helper text. */
32	  note: string;
33	};
34	
35	/* ---------------------------------------------------------------------------
36	 * Text handling
37	 * ------------------------------------------------------------------------ */
38	
39	const STOPWORDS = new Set([
40	  "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "from", "get",
41	  "has", "have", "he", "her", "his", "how", "i", "in", "is", "it", "its", "me",
42	  "my", "of", "on", "or", "our", "she", "so", "that", "the", "their", "them",
43	  "then", "there", "these", "they", "this", "to", "us", "was", "we", "were",
44	  "what", "when", "where", "which", "who", "will", "with", "you", "your",
45	  "business", "company", "startup", "brand", "new", "want", "need", "make",
