52	/** Lowercase alphabetic tokens, stopwords dropped, order preserved. */
53	export function tokenize(text: string): string[] {
54	  return (text || "")
55	    .toLowerCase()
56	    .replace(/[^a-z0-9\s'-]/g, " ")
57	    .split(/[\s'-]+/)
58	    .map((w) => w.replace(/[^a-z0-9]/g, ""))
59	    .filter((w) => w.length > 1 && !STOPWORDS.has(w));
60	}
