62	/** Strip a candidate down to a legal DNS label, or null if nothing survives. */
63	export function normalizeSld(raw: string): string | null {
64	  const s = (raw || "")
65	    .toLowerCase()
66	    .trim()
67	    .replace(/^https?:\/\//, "")
68	    .replace(/\..*$/, "") // drop anything the model appended as a TLD
69	    .replace(/[^a-z0-9-]/g, "")
70	    .replace(/^-+|-+$/g, "");
71	  if (s.length < 3 || s.length > 30) return null;
72	  if (s.startsWith("xn--")) return null; // punycode — not something we coin
73	  if (/^\d+$/.test(s)) return null;
74	  return s;
75	}
