77	/* ---------------------------------------------------------------------------
78	 * Scoring
79	 * ------------------------------------------------------------------------ */
80	
81	const VOWELS = new Set(["a", "e", "i", "o", "u", "y"]);
82	
83	/** Rough syllable count — good enough to reject unsayable strings. */
84	function syllables(word: string): number {
85	  let count = 0;
86	  let prevVowel = false;
87	  for (const ch of word) {
88	    const isVowel = VOWELS.has(ch);
89	    if (isVowel && !prevVowel) count++;
90	    prevVowel = isVowel;
91	  }
92	  return Math.max(1, count);
93	}
94	
95	/** Longest run of consecutive consonants — 4+ is usually unpronounceable. */
96	function maxConsonantRun(word: string): number {
97	  let run = 0;
98	  let best = 0;
99	  for (const ch of word) {
100	    if (VOWELS.has(ch)) run = 0;
101	    else {
102	      run++;
103	      if (run > best) best = run;
104	    }
105	  }
106	  return best;
107	}
108	
109	/**
110	 * Heuristic quality score (higher is better). Rewards short, sayable, one- or
111	 * two-word names that still echo the visitor's keywords; punishes hyphens,
112	 * digits, triple letters and consonant pile-ups.
113	 */
114	export function scoreSld(sld: string, keywords: string[]): number {
115	  let score = 100;
116	
117	  // Length: 6-12 characters is the sweet spot for a memorable brand.
118	  const len = sld.length;
119	  if (len <= 5) score += 6;
120	  else if (len <= 9) score += 12;
121	  else if (len <= 12) score += 4;
122	  else if (len <= 16) score -= 10;
123	  else score -= 26;
124	
125	  // Pronounceability.
126	  const syl = syllables(sld);
127	  if (syl <= 3) score += 8;
128	  else if (syl === 4) score -= 4;
129	  else score -= 14;
130	
131	  const run = maxConsonantRun(sld);
132	  if (run >= 5) score -= 30;
133	  else if (run === 4) score -= 14;
134	
135	  // Typing hazards.
136	  if (sld.includes("-")) score -= 22;
137	  if (/\d/.test(sld)) score -= 18;
138	  if (/(.)\1\1/.test(sld)) score -= 20; // three of the same letter
139	  if (/(.)\1$/.test(sld)) score -= 4; // doubled letter at a join, e.g. "brewwave"
140	
141	  // Awkward seams from naive concatenation.
142	  if (/([bcdfgjkpqtvxz])\1/.test(sld)) score -= 8;
143	
144	  // Relevance: some echo of the brief is good, a verbatim keyword dump is not.
145	  const hits = keywords.filter((k) => k.length > 3 && sld.includes(k)).length;
146	  if (hits === 1) score += 10;
147	  else if (hits >= 2) score -= 6;
148	
149	  // At least one vowel, please.
150	  if (!/[aeiouy]/.test(sld)) score -= 40;
151	
152	  return score;
153	}
