155	/* ---------------------------------------------------------------------------
156	 * Seeded RNG so results vary between visitors but stay reproducible per brief
157	 * ------------------------------------------------------------------------ */
158	
159	function makeRng(seedText: string): () => number {
160	  let h = 2166136261;
161	  for (let i = 0; i < seedText.length; i++) {
162	    h ^= seedText.charCodeAt(i);
163	    h = Math.imul(h, 16777619);
164	  }
165	  let state = h >>> 0 || 1;
166	  return () => {
167	    state ^= state << 13;
168	    state ^= state >>> 17;
169	    state ^= state << 5;
170	    state >>>= 0;
171	    return state / 4294967296;
172	  };
173	}
174	
175	function pick<T>(arr: T[], rng: () => number): T {
176	  return arr[Math.floor(rng() * arr.length) % arr.length];
177	}
178	
179	function shuffled<T>(arr: T[], rng: () => number): T[] {
180	  const out = arr.slice();
181	  for (let i = out.length - 1; i > 0; i--) {
182	    const j = Math.floor(rng() * (i + 1));
183	    [out[i], out[j]] = [out[j], out[i]];
184	  }
185	  return out;
186	}
