188	/* ---------------------------------------------------------------------------
189	 * Topic vocabulary lookup
190	 * ------------------------------------------------------------------------ */
191	
192	/** Related brand roots for a brief, drawn from the curated topic vocabulary. */
193	export function topicRoots(text: string): string[] {
194	  const haystack = (text || "").toLowerCase().replace(/[^a-z]/g, "");
195	  const out: string[] = [];
196	  for (const [topic, words] of Object.entries(TOPIC_WORDS)) {
197	    if (haystack.includes(topic)) out.push(...words);
198	  }
199	  // A couple of common two-word topics the substring match would miss.
200	  if (/realestate|realtor|property|letting|landlord/.test(haystack)) out.push(...(TOPIC_WORDS.realestate ?? []));
201	  if (/onlinestore|webshop|dropship/.test(haystack)) out.push(...(TOPIC_WORDS.ecommerce ?? []));
202	  return [...new Set(out)];
203	}
204	
205	/** Trim a word to a blendable stem (drops a trailing vowel-cluster). */
206	function stem(word: string): string {
207	  if (word.length <= 4) return word;
208	  let s = word.replace(/(ing|ers|er|ies|ed|es|s|y)$/, "");
209	  if (s.length < 3) s = word;
210	  return s;
211	}
212	
213	/** Take the leading consonant-vowel chunk of a word, for portmanteaus. */
214	function head(word: string, target = 4): string {
215	  const s = stem(word);
216	  if (s.length <= target) return s;
217	  let cut = target;
218	  // Prefer cutting after a vowel so the blend stays sayable.
219	  while (cut < s.length && !VOWELS.has(s[cut - 1])) cut++;
220	  return s.slice(0, Math.min(cut, target + 2));
221	}
222	
223	/** Take the trailing chunk of a word starting at a vowel, for portmanteaus. */
224	function tail(word: string, target = 4): string {
225	  const s = stem(word);
226	  if (s.length <= target) return s;
227	  let start = s.length - target;
228	  while (start > 0 && !VOWELS.has(s[start])) start--;
229	  return s.slice(start);
230	}
