232	/* ---------------------------------------------------------------------------
233	 * Generation
234	 * ------------------------------------------------------------------------ */
235	
236	export type GenerateInput = {
237	  idea: string;
238	  keywords?: string;
239	  tone?: Tone;
240	  /** How many labels to return. The API caps this well below any sane limit. */
241	  limit: number;
242	};
243	
244	/**
245	 * Build a ranked, de-duplicated list of candidate second-level labels using
246	 * blend / affix / synonym / real-word strategies. Never throws; returns fewer
247	 * than `limit` only if the banks genuinely run dry (they don't in practice).
248	 */
249	export function generateCandidates({ idea, keywords, tone = "any", limit }: GenerateInput): Candidate[] {
250	  const brief = `${idea} ${keywords ?? ""}`.trim();
251	  const rng = makeRng(`${brief}|${tone}`);
252	
253	  const briefWords = tokenize(brief);
254	  const kw = tokenize(keywords ?? "");
255	  // Keyword tokens first, then the most substantial words from the description.
256	  const seeds = [...new Set([...kw, ...briefWords])].filter((w) => w.length >= 3).slice(0, 8);
257	  const roots = topicRoots(brief);
258	
259	  const toneBank = tone === "any" ? [] : TONE_WORDS[tone] ?? [];
260	  const flavour = shuffled([...roots, ...toneBank], rng);
261	
262	  // The word pool a compound's second half is drawn from.
263	  const secondHalf = shuffled(
264	    [
265	      ...roots,
266	      ...toneBank,
267	      ...BRAND_SUFFIXES,
268	      ...STANDALONE_WORDS.slice(0, 30),
269	    ],
270	    rng,
271	  );
272	
273	  const out = new Map<string, Candidate>();
274	  const add = (raw: string, style: NameStyle, note: string) => {
275	    const sld = normalizeSld(raw);
276	    if (!sld) return;
277	    if (!out.has(sld)) out.set(sld, { sld, style, note });
278	  };
279	
280	  const strategies: Array<() => void> = [];
281	
282	  // 1. Compound — a seed or topic root plus a second word.
283	  strategies.push(() => {
284	    const firsts = shuffled([...seeds.map(stem), ...flavour.slice(0, 10)], rng).slice(0, 10);
285	    for (const a of firsts) {
286	      for (let i = 0; i < 3; i++) {
287	        const b = pick(secondHalf, rng);
288	        if (!b || b === a || a.includes(b) || b.includes(a)) continue;
289	        add(`${a}${b}`, "compound", "Two familiar words — easy to say and spell.");
290	      }
291	    }
292	  });
293	
294	  // 2. Portmanteau / coined blend — halves of two words fused.
295	  strategies.push(() => {
296	    const pool = shuffled([...seeds, ...flavour.slice(0, 12), ...COINED_ROOTS], rng);
297	    for (let i = 0; i < pool.length - 1 && i < 18; i++) {
298	      const a = head(pool[i], 4);
299	      const b = tail(pool[i + 1], 4);
300	      if (!a || !b || a === b) continue;
301	      // Avoid a doubled letter at the seam.
302	      const joined = a[a.length - 1] === b[0] ? a + b.slice(1) : a + b;
303	      add(joined, "invented", "Coined blend — no baggage, easy to trademark.");
304	    }
305	  });
306	
307	  // 3. Affix — brandable prefix or suffix on a real root.
308	  strategies.push(() => {
309	    const bases = shuffled([...seeds.map(stem), ...flavour.slice(0, 8)], rng).slice(0, 8);
310	    for (const base of bases) {
311	      if (rng() < 0.5) {
312	        add(`${pick(BRAND_PREFIXES, rng)}${base}`, "playful", "Verb-first — reads like an invitation.");
313	      } else {
314	        add(`${base}${pick(BRAND_SUFFIXES, rng)}`, "compound", "Root plus a product-shaped suffix.");
315	      }
316	    }
317	  });
318	
319	  // 4. Real word — an evocative standalone, biased toward the topic vocabulary.
320	  strategies.push(() => {
321	    const pool = shuffled([...roots, ...STANDALONE_WORDS], rng).slice(0, 14);
322	    for (const w of pool) {
323	      if (w.length < 4) continue;
324	      add(w, "real-word", "A real word that carries meaning on its own.");
325	    }
326	  });
327	
328	  // 5. Clipped invented — drop a trailing vowel or double a consonant.
329	  strategies.push(() => {
330	    const pool = shuffled([...seeds, ...roots, ...COINED_ROOTS], rng).slice(0, 12);
331	    for (const w of pool) {
332	      if (w.length < 5) continue;
333	      if (VOWELS.has(w[w.length - 1])) add(w.slice(0, -1), "invented", "Clipped spelling — shorter and distinctive.");
334	      add(`${w}r`, "invented", "Coined variant of a word you already use.");
335	    }
336	  });
337	
338	  // 6. Descriptive pair — literal, for people who want to be found not admired.
339	  strategies.push(() => {
340	    if (seeds.length < 2) return;
341	    const s = shuffled(seeds, rng);
342	    for (let i = 0; i + 1 < s.length && i < 6; i++) {
343	      add(`${s[i]}${s[i + 1]}`, "descriptive", "Says what you do — good for search intent.");
344	    }
345	    for (const w of s.slice(0, 4)) {
346	      add(`${w}${pick(["hq", "co", "studio", "group", "collective"], rng)}`, "descriptive", "Literal name with a business-shaped tail.");
347	    }
348	  });
349	
350	  // Descriptive tone leads with the literal strategy; invented leads with blends.
351	  if (tone === "descriptive") strategies.unshift(strategies.pop()!);
352	  if (tone === "invented") strategies.unshift(strategies.splice(1, 1)[0]);
353	
354	  for (const run of strategies) run();
355	
356	  const ranked = [...out.values()]
357	    .map((c) => ({ c, score: scoreSld(c.sld, seeds) }))
358	    .filter((x) => x.score > 45)
359	    .sort((a, b) => b.score - a.score);
360	
361	  // Interleave styles so the results page isn't ten compounds in a row.
362	  const byStyle = new Map<NameStyle, Candidate[]>();
363	  for (const { c } of ranked) {
364	    const list = byStyle.get(c.style) ?? [];
365	    list.push(c);
366	    byStyle.set(c.style, list);
367	  }
368	  const order: NameStyle[] = tone === "descriptive"
369	    ? ["descriptive", "compound", "real-word", "invented", "playful"]
370	    : ["compound", "invented", "real-word", "descriptive", "playful"];
371	
372	  const result: Candidate[] = [];
373	  let exhausted = false;
374	  while (result.length < limit && !exhausted) {
375	    exhausted = true;
376	    for (const style of order) {
377	      const list = byStyle.get(style);
378	      if (list && list.length) {
379	        result.push(list.shift()!);
380	        exhausted = false;
381	        if (result.length >= limit) break;
382	      }
383	    }
384	  }
385	  return result;
386	}
