2	import { requireUser } from "@/lib/auth";
3	import { registrarConfigured, checkDomains, type DomainCheck } from "@/lib/registrar";
4	import { PageHeader, EmptyState } from "@/components/ui/primitives";
5	import { DomainRegisterWizard } from "@/components/customer/DomainRegisterWizard";
6	
7	export const dynamic = "force-dynamic";
8	
9	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
10	
11	export default async function RegisterDomainPage({
12	  searchParams,
13	}: {
14	  searchParams: Promise<{ domain?: string }>;
15	}) {
16	  const user = await requireUser();
17	  const { domain: raw } = await searchParams;
18	  const domain = (raw ?? "").toLowerCase().trim();
19	  const valid = DOMAIN_RE.test(domain);
20	  const configured = registrarConfigured();
21	
22	  if (!configured) {
23	    return (
24	      <div className="space-y-6">
25	        <PageHeader title="Register domain" />
26	        <EmptyState
27	          title="Domain registration is not available yet"
28	          sub="Registration activates once the registrar integration is configured. Your existing domains stay manageable in the meantime."
29	          action={
30	            <Link href="/dashboard/domains" className="btn-primary">
31	              Back to domains
32	            </Link>
33	          }
34	        />
35	      </div>
36	    );
37	  }
38	
39	  // Live availability + price for the pre-selected domain (best-effort).
40	  let initialCheck: DomainCheck | null = null;
41	  if (valid) {
42	    try {
43	      const [check] = await checkDomains([domain]);
44	      initialCheck = check ?? null;
45	    } catch {
46	      /* registrar briefly unreachable — the wizard can re-check client-side */
47	    }
48	  }
49	
50	  return (
51	    <div className="space-y-6">
52	      <PageHeader title="Register domain" sub="A few quick steps to secure your name.">
53	        <Link href="/dashboard/domains" className="btn-ghost">
54	          ← All domains
55	        </Link>
56	      </PageHeader>
57	
58	      <DomainRegisterWizard
59	        initialDomain={valid ? domain : ""}
60	        initialCheck={initialCheck}
61	        defaultEmail={user.email}
62	        balanceCents={user.balanceCents}
63	      />
64	    </div>
65	  );
66	}
