1	/**
2	 * Shared source-reading helpers for the structural tripwire suites.
3	 *
4	 * NOT named `*.test.ts` on purpose: `npm test` globs `test/*.test.ts`, so this
5	 * module is imported, never executed as a suite. It used to live inside
6	 * customer-actions-guards.test.ts and be imported from there, which made every
7	 * assertion in that file run a second time under the importing suite's name.
8	 */
9	
10	/**
11	 * Blank out the CONTENTS of every string / template literal, on top of
12	 * `stripComments`. Quotes and backticks are kept so the token stream still
13	 * parses by eye; only what is between them is erased.
14	 *
15	 * `${…}` interpolations inside a template literal are KEPT, because they are
16	 * executable code, not string content. Erasing them would hide exactly the
17	 * detail some tripwires exist to check — a rate-limit bucket keyed on
18	 * `` `x:${user.id}` `` versus one keyed on `` `x:${clientIp}` `` is the
19	 * difference between limiting an account and limiting a forgeable header, and
20	 * both collapse to the same blank if the interpolation goes with the text.
21	 *
22	 * WHY BOTH ARE NEEDED. `stripComments` deliberately preserves literals (there is
23	 * a test asserting exactly that), because plenty of tripwires need to read a
24	 * literal — "is MAIL_HOST still `mail.nxeon.cloud`?". But a tripwire asserting a
25	 * CALL is present must not match a mention of that call inside a string, and
26	 * this repo is full of such mentions: error copy, audit-log `action` values, and
27	 * doc strings that quote the very function being checked. Comments alone are not
28	 * enough here — `"Couldn't apply forwarding on the mail server"` and
29	 * `detail: "mailbox.suspend"` are executable code, and a naive grep is happy
30	 * with either.
31	 *
32	 * So: use `stripComments` when the assertion is ABOUT a literal's value, and
33	 * this when the assertion is about code SHAPE.
34	 */
35	export function stripCommentsAndStrings(src: string): string {
36	  const s = stripComments(src);
37	  const n = s.length;
38	  let out = "";
39	  let i = 0;
40	
41	  /** Consume the body of a literal opened by `quote` at `i`, appending to `out`. */
42	  const literal = (quote: string) => {
43	    out += quote;
44	    i++;
45	    while (i < n) {
46	      const c = s[i];
47	      if (c === "\\") {
48	        // Escapes are consumed whole so `\"` never closes the literal.
49	        i += 2;
50	        continue;
51	      }
52	      if (c === quote) break;
53	      // Newlines survive so line numbers in a failure still line up.
54	      if (c === "\n") out += "\n";
55	      if (quote === "`" && c === "$" && s[i + 1] === "{") {
56	        // An interpolation is code. Copy it verbatim, tracking brace depth so a
57	        // nested object/template inside it doesn't end it early.
58	        out += "${";
59	        i += 2;
60	        let depth = 1;
61	        while (i < n && depth > 0) {
62	          const d = s[i];
63	          if (d === "{") depth++;
64	          else if (d === "}") depth--;
65	          else if (d === '"' || d === "'" || d === "`") {
66	            literal(d); // nested literal — its own contents get blanked
67	            continue;
68	          }
69	          if (depth > 0) out += d;
70	          i++;
71	        }
72	        out += "}";
73	        continue;
74	      }
75	      i++;
76	    }
77	    if (i < n) out += s[i];
78	    i++;
79	  };
80	
81	  // A `/`-delimited regex literal may contain quote characters inside a character
82	  // class — e.g. `/[^"'<>]+/`. Without regex awareness the loop below sees that
83	  // `'` as the start of a string and swallows the rest of the file to the next
84	  // quote, silently returning near-empty source. That made every tripwire run over
85	  // a file containing such a regex VACUOUS — it happened to `lib/email-render.ts`,
86	  // whose `SECRET_QUERY_PARAM` is exactly `/…[^&"'<>\s#]+/gi`, blanking the whole
87	  // module so a security assertion passed against nothing. `stripComments` already
88	  // skips regexes correctly (tracking `[` … `]`); this pass now does too.
89	  const REGEX_PRECEDERS = new Set([
90	    "", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n",
91	  ]);
92	  let prev = "";
93	  const consumeRegex = () => {
94	    out += s[i]; // opening /
95	    i++;
96	    let inClass = false;
97	    for (; i < n; i++) {
98	      const r = s[i];
99	      out += r;
100	      if (r === "\\") {
101	        if (i + 1 < n) out += s[i + 1];
102	        i++;
103	        continue;
104	      }
105	      if (r === "[") inClass = true;
106	      else if (r === "]") inClass = false;
107	      else if (r === "/" && !inClass) { i++; break; }
108	      else if (r === "\n") { i++; break; } // unterminated — stop rather than run away
109	    }
110	    prev = "/";
111	  };
112	
113	  while (i < n) {
114	    const c = s[i];
115	    if (c === '"' || c === "'" || c === "`") {
116	      literal(c);
117	      prev = c;
118	      continue;
119	    }
120	    // `//` and `/*` were already removed by stripComments, so a `/` after a
121	    // regex-preceding token here is a genuine literal, not division.
122	    if (c === "/" && (REGEX_PRECEDERS.has(prev) || /\b(return|typeof|case|in|of|new|do|else|yield|await)\s*$/.test(out))) {
123	      consumeRegex();
124	      continue;
125	    }
126	    out += c;
127	    if (!/\s/.test(c) || c === "\n") prev = c;
128	    i++;
129	  }
130	  return out;
131	}
132	
133	export function stripComments(src: string): string {
134	  let out = "";
135	  let i = 0;
136	  const n = src.length;
137	  let quote: string | null = null;
138	  /** Last non-whitespace character emitted — decides `/` = regex vs. division. */
139	  let prev = "";
140	
141	  /** Positions where a `/` begins a regex literal rather than a division. */
142	  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
143	  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;
144	
145	  while (i < n) {
146	    const c = src[i];
147	    const next = src[i + 1];
148	
149	    if (quote) {
150	      out += c;
151	      if (c === "\\") {
152	        // Escape: copy the escaped character too, so `\"` never closes a string.
153	        if (i + 1 < n) out += src[i + 1];
154	        i += 2;
155	        continue;
156	      }
157	      if (c === quote) quote = null;
158	      i++;
159	      continue;
160	    }
161	
162	    if (c === '"' || c === "'" || c === "`") {
163	      quote = c;
164	      out += c;
165	      prev = c;
166	      i++;
167	      continue;
168	    }
169	
170	    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
171	    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
172	    // the regex branch below only ever sees a genuine literal.
173	    if (c === "/" && next === "/") {
174	      while (i < n && src[i] !== "\n") i++;
175	      out += " ";
176	      continue;
177	    }
178	    if (c === "/" && next === "*") {
179	      i += 2;
180	      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
181	      i += 2;
182	      out += " ";
183	      continue;
184	    }
185	
186	    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
187	    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
188	    // line — silently deleting real code from everything asserted below.
189	    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
190	      out += c;
191	      i++;
192	      let inClass = false;
193	      for (; i < n; i++) {
194	        const r = src[i];
195	        out += r;
196	        if (r === "\\") {
197	          if (i + 1 < n) out += src[i + 1];
198	          i++;
199	          continue;
200	        }
201	        if (r === "[") inClass = true;
202	        else if (r === "]") inClass = false;
203	        else if (r === "/" && !inClass) {
204	          i++;
205	          break;
206	        } else if (r === "\n") {
207	          // Not a regex after all (unterminated) — stop rather than run away.
208	          i++;
209	          break;
210	        }
211	      }
212	      prev = "/";
213	      continue;
214	    }
215	
216	    out += c;
217	    if (!/\s/.test(c) || c === "\n") prev = c;
218	    i++;
219	  }
220	  return out;
221	}
