1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { checkDomains, registrarConfigured } from "@/lib/registrar";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	
7	export async function GET(req: NextRequest) {
8	  const user = await currentUser();
9	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
10	
11	  // Each call fans out to the registrar API — throttle per-IP so a customer
12	  // can't hammer the upstream registrar / rack up lookups.
13	  const rl = checkRateLimit(`domcheck:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
14	  if (!rl.ok) {
15	    return NextResponse.json(
16	      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
17	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
18	    );
19	  }
20	
21	  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
22	  if (q.length < 2) return NextResponse.json({ results: [] });
23	  if (!registrarConfigured()) {
24	    return NextResponse.json({ configured: false, results: [] });
25	  }
26	
27	  const base = q.includes(".") ? q.slice(0, q.indexOf(".")) : q;
28	  const candidates = q.includes(".")
29	    ? [q, ...["com", "net", "io", "dev"].filter((t) => q !== `${base}.${t}`).map((t) => `${base}.${t}`)]
30	    : ["com", "net", "io", "dev", "app", "xyz"].map((t) => `${base}.${t}`);
31	
32	  try {
33	    const checks = await checkDomains(candidates.slice(0, 8));
34	    return NextResponse.json({
35	      configured: true,
36	      results: checks.filter((c) => c.priceCents !== null),
37	    });
38	  } catch (e: any) {
39	    return NextResponse.json({ configured: true, error: String(e?.message ?? e).slice(0, 200), results: [] });
40	  }
41	}
