11	test("vpsTerm returns the matching term by months", () => {
12	  assert.equal(vpsTerm(1).months, 1);
13	  assert.equal(vpsTerm(12).discountPct, 10);
14	  assert.equal(vpsTerm(24).discountPct, 15);
15	  assert.equal(vpsTerm(36).discountPct, 20);
16	});
17	
18	test("vpsTerm falls back to the monthly term for unknown durations", () => {
19	  assert.deepEqual(vpsTerm(7), VPS_TERMS[0]);
20	  assert.deepEqual(vpsTerm(0), VPS_TERMS[0]);
21	  assert.deepEqual(vpsTerm(-5), VPS_TERMS[0]);
22	});
23	
24	test("vpsTermPriceCents applies commitment discounts", () => {
25	  const monthly = 1000; // $10.00/mo
26	  // 1 mo: no discount
27	  assert.equal(vpsTermPriceCents(monthly, 1), 1000);
28	  // 12 mo -10%: 12000 * 0.90 = 10800
29	  assert.equal(vpsTermPriceCents(monthly, 12), 10800);
30	  // 24 mo -15%: 24000 * 0.85 = 20400
31	  assert.equal(vpsTermPriceCents(monthly, 24), 20400);
32	  // 36 mo -20%: 36000 * 0.80 = 28800
33	  assert.equal(vpsTermPriceCents(monthly, 36), 28800);
34	});
35	
36	test("vpsTermPriceCents rounds to whole cents", () => {
37	  // 333 * 12 * 0.9 = 3596.4 -> 3596
38	  assert.equal(vpsTermPriceCents(333, 12), 3596);
39	});
40	
41	test("vpsEffectiveMonthly reflects the discounted per-month price", () => {
42	  // annual $10/mo -> 10800/12 = 900
43	  assert.equal(vpsEffectiveMonthly(1000, 12), 900);
44	  // monthly term is unchanged
45	  assert.equal(vpsEffectiveMonthly(1000, 1), 1000);
46	});
