48	test("addMonths advances the calendar month", () => {
49	  const from = new Date("2026-01-15T00:00:00.000Z");
50	  const plus1 = addMonths(from, 1);
51	  assert.equal(plus1.getUTCMonth(), new Date("2026-02-15T00:00:00.000Z").getUTCMonth());
52	  // 12 months forward lands in the next year
53	  const plus12 = addMonths(from, 12);
54	  assert.equal(plus12.getUTCFullYear(), from.getUTCFullYear() + 1);
55	});
