64	/**
65	 * REAL DEFECT (2026-07-27 money-core audit): `vpsEffectiveMonthly` divided by
66	 * `months` with no guard, so `months <= 0` produced `0 / 0` = NaN. That is not a
67	 * display problem. `prorateDeltaCents` (lib/proration.ts) prices BOTH halves of
68	 * every upgrade charge and downgrade credit through this function using
69	 * `Server.termMonths`, and NaN does not stop at the clamp: `Math.max(0, NaN)` is
70	 * NaN, because NaN is not greater than 0. The NaN travels on as the amount to
71	 * debit — past `if (cents <= 0) return` in debitWallet, which NaN also fails — and
72	 * lands in a Prisma `decrement`. The column defaults to 1 and every writer clamps
73	 * to >= 1 today, so this is a latch rather than a live bug; a shared money function
74	 * still must not be able to emit a NaN.
75	 */
76	test("a zero or negative term never produces NaN money", () => {
77	  assert.equal(vpsEffectiveMonthly(899, 0), 899, "no term discount to spread — the monthly price stands");
78	  assert.equal(vpsEffectiveMonthly(899, -12), 899);
79	  assert.equal(vpsEffectiveMonthly(899, Number.NaN), 899);
80	  for (const months of [0, -12, Number.NaN]) {
81	    assert.ok(Number.isFinite(vpsEffectiveMonthly(899, months)), `months=${months} must stay finite`);
82	  }
83	  // The clamp that everyone assumes protects them does NOT stop a NaN.
84	  assert.ok(Number.isNaN(Math.max(0, Number.NaN)), "which is exactly why the guard has to be here");
85	});
