/**
 * Shared brief → names → live availability → ranked results pipeline.
 *
 * BOTH surfaces of the domain-name generator run through here:
 *   - the public, SEO marketing tool  (app/api/tools/domain-generator/route.ts)
 *   - the signed-in customer portal    (app/api/dashboard/domains/generate/route.ts)
 *
 * The orchestration lived inline in the public route. A second copy for the
 * portal would have been this codebase's single most common defect — two answers
 * to "how do we turn a brief into available names", drifting apart. So the whole
 * pipeline is one function, `generateSuggestions`, and each route contributes
 * only what genuinely differs: how the caller is identified and throttled, and
 * whether the visitor is signed in.
 *
 * Honesty invariants enforced here, not in the UI:
 *   - a result is only ever "available" when the REGISTRAR returned a real price
 *     for it (that guarantee comes from domain-availability.ts and is preserved
 *     verbatim by `toSuggestResult`);
 *   - when the registrar can't be reached the name degrades to "unknown"
 *     ("couldn't verify"), never to "available";
 *   - a price is only carried when the registrar gave one.
 *
 * The small helpers (`readTlds`, `buildDomains`, `mergeCandidates`,
 * `toSuggestResult`, `rankSuggestions`, `partitionResults`) are pure and are
 * unit-tested in test/domain-suggest.test.ts.
 */

import { aiAvailable, aiCandidates } from "./domain-ai";
import { checkAvailabilityBatched, type DomainResult } from "./domain-availability";
import { generateCandidates, type Candidate } from "./domain-generate";
import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "./domain-vocab";

/** Distinct name ideas per request. Caps the single Claude call's output. */
export const MAX_NAMES = 12;

/** Absolute ceiling on registrar lookups per request (names × TLDs). */
export const MAX_LOOKUPS = 24;

/** TLDs a caller may select at once. */
export const MAX_TLDS = 3;

export const MAX_IDEA_LEN = 400;
export const MAX_KEYWORDS_LEN = 120;

/** A brief shorter than this is rejected before any AI or registrar spend. */
export const MIN_IDEA_LEN = 8;

const VALID_TONES = new Set(TONES.map((t) => t.value));

export type SuggestStatus = "available" | "taken" | "unknown";

export type SuggestResult = {
  domain: string;
  sld: string;
  tld: string;
  status: SuggestStatus;
  premium: boolean;
  /** Retail first-year price in integer cents, or null when the registrar gave none. */
  priceCents: number | null;
  /** Retail renewal price in integer cents, or null. */
  renewCents: number | null;
  style: string;
  note: string;
};

export type SuggestResponse = {
  /** "ai" when Claude produced the names, "heuristic" when the fallback did. */
  source: "ai" | "heuristic";
  /** False when the registrar isn't configured — every result is "unknown". */
  registrarConfigured: boolean;
  /** True when we skipped some registrar lookups to protect the shared budget. */
  throttled: boolean;
  checked: number;
  tlds: string[];
  results: SuggestResult[];
};

/* ---------------------------------------------------------------------------
 * Input normalisation — pure
 * ------------------------------------------------------------------------ */

/** Collapse whitespace, trim, and hard-cap length. Non-strings become "". */
export function readString(v: unknown, max: number): string {
  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
}

export function readIdea(v: unknown): string {
  return readString(v, MAX_IDEA_LEN);
}

export function readKeywords(v: unknown): string {
  return readString(v, MAX_KEYWORDS_LEN);
}

/** Coerce arbitrary input to a known tone, defaulting to "any". */
export function readTone(v: unknown): Tone {
  const raw = readString(v, 20) as Tone;
  return VALID_TONES.has(raw) ? raw : "any";
}

/**
 * Sanitise the requested TLD list: lower-cased, de-dotted, de-duplicated, only
 * ones we actually offer, capped at MAX_TLDS. Falls back to the defaults when
 * nothing valid survives.
 */
export function readTlds(v: unknown): string[] {
  if (!Array.isArray(v)) return [...DEFAULT_TLDS];
  const out: string[] = [];
  for (const raw of v) {
    if (typeof raw !== "string") continue;
    const tld = raw.toLowerCase().replace(/^\./, "").trim();
    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
    if (out.length >= MAX_TLDS) break;
  }
  return out.length ? out : [...DEFAULT_TLDS];
}

/* ---------------------------------------------------------------------------
 * Candidate assembly — pure
 * ------------------------------------------------------------------------ */

/**
 * Fill `primary` (the AI names) up to `max` with `fallback` (heuristic names),
 * de-duplicating on the bare label. Primary keeps its order and priority; the
 * fallback only ever tops up a short or missing AI list.
 */
export function mergeCandidates(
  primary: Candidate[] | null,
  fallback: Candidate[],
  max: number,
): Candidate[] {
  const merged = primary ? primary.slice(0, max) : [];
  if (merged.length >= max) return merged;
  const seen = new Set(merged.map((c) => c.sld));
  for (const c of fallback) {
    if (merged.length >= max) break;
    if (seen.has(c.sld)) continue;
    seen.add(c.sld);
    merged.push(c);
  }
  return merged;
}

/**
 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
 * caller's first-choice extension is checked for every name before we spend any
 * budget on the second choice.
 */
export function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
  const domains: string[] = [];
  for (const tld of tlds) {
    for (const c of candidates) {
      if (domains.length >= MAX_LOOKUPS) return domains;
      domains.push(`${c.sld}.${tld}`);
    }
  }
  return domains;
}

/* ---------------------------------------------------------------------------
 * Result shaping — pure
 * ------------------------------------------------------------------------ */

/**
 * Combine a registrar availability result with its candidate's copy. The
 * availability status is carried through UNCHANGED — an "unknown" (couldn't
 * verify) is never promoted to "available" here, and a price only survives when
 * the registrar actually returned one.
 */
export function toSuggestResult(r: DomainResult, meta?: Pick<Candidate, "style" | "note">): SuggestResult {
  const dot = r.domain.lastIndexOf(".");
  const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
  const tld = dot >= 0 ? r.domain.slice(dot + 1) : "";
  return {
    domain: r.domain,
    sld,
    tld,
    status: r.status,
    premium: r.premium,
    priceCents: r.priceCents,
    renewCents: r.renewCents,
    style: meta?.style ?? "invented",
    note: meta?.note ?? "",
  };
}

/** A name we can put a "Register" button on: verified free with a real price. */
export function isRegisterable(r: SuggestResult): boolean {
  return r.status === "available" && r.priceCents !== null;
}

/** Available first (cheapest first within that), then unknown, then taken. Mutates + returns. */
export function rankSuggestions(results: SuggestResult[]): SuggestResult[] {
  const rank: Record<SuggestStatus, number> = { available: 0, unknown: 1, taken: 2 };
  results.sort(
    (a, b) =>
      rank[a.status] - rank[b.status] ||
      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
      a.domain.length - b.domain.length,
  );
  return results;
}

/**
 * Split results into the three buckets both UIs render. `available` is the
 * differentiator: only genuinely-free, priced names. `unchecked` are the
 * "couldn't verify" names; `taken` are confirmed registered.
 */
export function partitionResults(results: SuggestResult[]): {
  available: SuggestResult[];
  unchecked: SuggestResult[];
  taken: SuggestResult[];
} {
  return {
    available: results.filter((r) => r.status === "available"),
    unchecked: results.filter((r) => r.status === "unknown"),
    taken: results.filter((r) => r.status === "taken"),
  };
}

/* ---------------------------------------------------------------------------
 * The pipeline — the one impure step (AI + registrar)
 * ------------------------------------------------------------------------ */

export type SuggestInput = {
  /** Already normalised + validated (>= MIN_IDEA_LEN) by the caller. */
  idea: string;
  keywords: string;
  tone: Tone;
  tlds: string[];
};

/**
 * Names then live availability. Never throws: a missing key falls back to the
 * heuristic generator, a registrar failure degrades to "unknown". Returns a
 * response body with everything both routes need EXCEPT `signedIn`, which each
 * route supplies for itself.
 *
 * When the brief yields no usable labels at all, `results` is empty and the
 * caller should surface a "try more detail" message rather than a page of
 * nothing — that is the ONLY time `results` is empty (taken/unknown names still
 * produce results).
 */
export async function generateSuggestions(input: SuggestInput): Promise<SuggestResponse> {
  const { idea, keywords, tone, tlds } = input;

  // 1) Names — Claude when the platform key is set, heuristics otherwise.
  let aiNames: Candidate[] | null = null;
  let source: "ai" | "heuristic" = "heuristic";
  if (aiAvailable()) {
    aiNames = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
    if (aiNames && aiNames.length) source = "ai";
  }
  const needFallback = !aiNames || aiNames.length < MAX_NAMES;
  const fallback = needFallback ? generateCandidates({ idea, keywords, tone, limit: MAX_NAMES }) : [];
  const candidates = mergeCandidates(aiNames, fallback, MAX_NAMES);

  const byLabel = new Map(candidates.map((c) => [c.sld, c]));

  // 2) Availability — one batched, cached, globally-throttled registrar call.
  const domains = buildDomains(candidates, tlds);
  const availability = await checkAvailabilityBatched(domains);

  const results = availability.results.map((r: DomainResult) => {
    const dot = r.domain.lastIndexOf(".");
    const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
    return toSuggestResult(r, byLabel.get(sld));
  });
  rankSuggestions(results);

  return {
    source,
    registrarConfigured: availability.configured,
    throttled: availability.throttled,
    checked: results.length,
    tlds,
    results,
  };
}

import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { jsonError } from "@/lib/tools/api";
import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
import {
  generateSuggestions,
  readIdea,
  readKeywords,
  readTlds,
  readTone,
  MIN_IDEA_LEN,
} from "@/lib/tools/domain-suggest";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * AI domain-name generator — public, unauthenticated, and therefore capped hard.
 *
 * The brief → names → live availability pipeline lives in `lib/tools/domain-suggest.ts`
 * and is shared verbatim with the signed-in portal route. This handler owns only
 * the public surface's concerns:
 *
 *   1. Two per-IP sliding windows (burst + hourly), keyed on the PROXY-ATTESTED
 *      address via the shared `toolRateLimitByIp` helper — never the spoofable
 *      first hop of X-Forwarded-For. One accepted request = at most one Claude
 *      call and one batched registrar lookup.
 *   2. Input validation, so a too-short brief costs nothing.
 *
 * Degradation is handled inside the pipeline: no ANTHROPIC_API_KEY (or any Claude
 * failure) falls back to the local heuristic generator; a registrar failure marks
 * names "unknown" rather than claiming they're free. Neither surfaces as an error.
 */

export async function POST(req: Request) {
  // Burst limit, then a longer window so a single IP can't grind all day.
  const burst = toolRateLimitByIp(req, "domain-generator", { max: 6, windowMs: 60_000 });
  if (burst) return burst;
  const hourly = toolRateLimitByIp(req, "domain-generator-hourly", { max: 40, windowMs: 60 * 60_000 });
  if (hourly) return hourly;

  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const idea = readIdea(body.idea);
  const keywords = readKeywords(body.keywords);
  const tone = readTone(body.tone);
  const tlds = readTlds(body.tlds);

  if (idea.length < MIN_IDEA_LEN) {
    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
  }

  const data = await generateSuggestions({ idea, keywords, tone, tlds });

  if (!data.results.length) {
    return jsonError("We couldn't build names from that description — try adding a little more detail.");
  }

  // Signed-in visitors go straight into the pre-filled registration wizard;
  // everyone else lands on signup with the name carried through.
  let signedIn = false;
  try {
    signedIn = Boolean(await currentUser());
  } catch {
    /* session lookup unavailable — treat as anonymous */
  }

  return NextResponse.json({ ok: true, signedIn, ...data });
}

