import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { jsonError } from "@/lib/tools/api";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  generateSuggestions,
  readIdea,
  readKeywords,
  readTlds,
  readTone,
  MIN_IDEA_LEN,
} from "@/lib/tools/domain-suggest";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Domain-name generator for the signed-in customer portal.
 *
 * Same brief → names → live availability pipeline as the public marketing tool
 * (both call `generateSuggestions`), but this surface is authenticated, so:
 *
 *   - The caller must be signed in.
 *   - Throttling keys on the ACCOUNT (`user.id`), a real identity, not the
 *     shared, spoofable client IP. A logged-in customer gets a more generous
 *     budget than an anonymous visitor while the platform Claude key and the
 *     metered registrar stay protected. (The IP-keyed limiter would lump a whole
 *     office behind one NAT into a single bucket; the account key is the honest
 *     one here.)
 *
 * Every "Register" the UI renders points at /dashboard/domains/register?domain=…,
 * the existing purchase path, which re-checks availability and price before charge.
 */

export async function POST(req: Request) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ ok: false, error: "Sign in to generate domain ideas." }, { status: 401 });
  }

  // Burst then hourly, both keyed on the account. AI + registrar cost money even
  // for a paying customer, so the windows are generous but not unbounded.
  const burst = checkRateLimit(`tool:domain-generator:user:${user.id}`, { max: 12, windowMs: 60_000 });
  if (!burst.ok) {
    return NextResponse.json(
      { ok: false, error: `You're generating quickly — try again in ${burst.retryAfterSec}s.` },
      { status: 429, headers: { "Retry-After": String(burst.retryAfterSec) } },
    );
  }
  const hourly = checkRateLimit(`tool:domain-generator-hourly:user:${user.id}`, { max: 120, windowMs: 60 * 60_000 });
  if (!hourly.ok) {
    return NextResponse.json(
      { ok: false, error: `Hourly generation limit reached — try again in ${hourly.retryAfterSec}s.` },
      { status: 429, headers: { "Retry-After": String(hourly.retryAfterSec) } },
    );
  }

  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const idea = readIdea(body.idea);
  const keywords = readKeywords(body.keywords);
  const tone = readTone(body.tone);
  const tlds = readTlds(body.tlds);

  if (idea.length < MIN_IDEA_LEN) {
    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
  }

  const data = await generateSuggestions({ idea, keywords, tone, tlds });

  if (!data.results.length) {
    return jsonError("We couldn't build names from that description — try adding a little more detail.");
  }

  // Always signed in on this route — the UI links straight to the register wizard.
  return NextResponse.json({ ok: true, signedIn: true, ...data });
}

"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { fmtMoney } from "@/components/ui/primitives";
import { DEFAULT_TLDS, SUGGESTABLE_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";

/**
 * Signed-in customer version of the AI domain-name generator.
 *
 * Same brief → names → live availability flow as the public marketing tool, but
 * rendered in the portal design system and wired straight into the existing
 * registration path: every available name links to
 * /dashboard/domains/register?domain=…, which re-checks the name and its price
 * before charging the wallet.
 *
 * Honesty, mirrored from the API's guarantees:
 *  - only genuinely-available, registrar-priced names get a Register button;
 *  - a name we couldn't verify is shown as "couldn't verify", never as free;
 *  - a price is only printed when the registrar actually returned one.
 */

type Status = "available" | "taken" | "unknown";

type Result = {
  domain: string;
  sld: string;
  tld: string;
  status: Status;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
  style: string;
  note: string;
};

type ApiResponse = {
  ok: true;
  source: "ai" | "heuristic";
  signedIn: boolean;
  registrarConfigured: boolean;
  throttled: boolean;
  checked: number;
  tlds: string[];
  results: Result[];
};

const MAX_TLDS = 3;
const MAX_IDEA = 400;

const STYLE_LABEL: Record<string, string> = {
  compound: "Compound",
  invented: "Invented",
  "real-word": "Real word",
  playful: "Playful",
  descriptive: "Descriptive",
};

const LOADING_STEPS = [
  "Reading your brief…",
  "Shaping name candidates…",
  "Checking live availability with the registrar…",
  "Pricing what's still free…",
];

const registerHref = (domain: string) => `/dashboard/domains/register?domain=${encodeURIComponent(domain)}`;

export function DomainIdeaGenerator({ configured }: { configured: boolean }) {
  const [idea, setIdea] = useState("");
  const [keywords, setKeywords] = useState("");
  const [tone, setTone] = useState<Tone>("any");
  const [tlds, setTlds] = useState<string[]>([...DEFAULT_TLDS]);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(0);
  const [error, setError] = useState("");
  const [data, setData] = useState<ApiResponse | null>(null);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  function toggleTld(tld: string) {
    setTlds((prev) => {
      if (prev.includes(tld)) return prev.length === 1 ? prev : prev.filter((t) => t !== tld);
      if (prev.length >= MAX_TLDS) return prev;
      return [...prev, tld];
    });
  }

  async function run(e?: React.SyntheticEvent) {
    e?.preventDefault();
    if (idea.trim().length < 8 || loading) return;
    setLoading(true);
    setError("");
    setData(null);
    setStep(0);
    timers.current.forEach(clearTimeout);
    timers.current = LOADING_STEPS.slice(1).map((_, i) => setTimeout(() => setStep(i + 1), 900 * (i + 1)));

    try {
      const res = await fetch("/api/dashboard/domains/generate", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ idea, keywords, tone, tlds }),
        cache: "no-store",
      });
      const json = await res.json();
      if (!res.ok || !json.ok) throw new Error(json.error || "We couldn't generate names just now.");
      setData(json as ApiResponse);
    } catch (err) {
      setError(err instanceof Error ? err.message : "We couldn't generate names just now.");
    } finally {
      timers.current.forEach(clearTimeout);
      setLoading(false);
    }
  }

  const available = data?.results.filter((r) => r.status === "available") ?? [];
  const unchecked = data?.results.filter((r) => r.status === "unknown") ?? [];
  const taken = data?.results.filter((r) => r.status === "taken") ?? [];

  return (
    <div className="card">
      <style>{`
        .nx-name-row { animation: nx-name-in .32s cubic-bezier(.22,1,.36,1) both; }
        @keyframes nx-name-in { from { opacity:0; transform: translateY(6px);} to { opacity:1; transform:none;} }
        .nx-skel { animation: nx-skel 1.2s ease-in-out infinite; }
        @keyframes nx-skel { 0%,100%{opacity:.35} 50%{opacity:.7} }
        @media (prefers-reduced-motion: reduce) { .nx-name-row, .nx-skel { animation: none !important; } }
      `}</style>

      <form onSubmit={run} className="space-y-5">
        <div>
          <label className="label">What are you building?</label>
          <textarea
            className="input min-h-[88px] resize-y leading-relaxed"
            placeholder="A subscription coffee roastery shipping single-origin beans to offices in Manchester"
            value={idea}
            maxLength={MAX_IDEA}
            onChange={(e) => setIdea(e.target.value)}
            spellCheck={false}
          />
          <p className="mt-1 text-xs text-slate-500">A sentence or two is plenty. The more specific, the better the names.</p>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div>
            <label className="label">Words to work in (optional)</label>
            <input
              className="input"
              placeholder="roast, office, origin"
              value={keywords}
              maxLength={120}
              onChange={(e) => setKeywords(e.target.value)}
              autoCapitalize="none"
              spellCheck={false}
            />
            <p className="mt-1 text-xs text-slate-500">Comma separated. Treated as hints, not rules.</p>
          </div>
          <div>
            <label className="label">Naming style</label>
            <select className="input" value={tone} onChange={(e) => setTone(e.target.value as Tone)}>
              {TONES.map((t) => (
                <option key={t.value} value={t.value}>
                  {t.label}
                </option>
              ))}
            </select>
            <p className="mt-1 text-xs text-slate-500">{TONES.find((t) => t.value === tone)?.hint}</p>
          </div>
        </div>

        <div>
          <span className="label">Extensions to check (up to {MAX_TLDS})</span>
          <div className="flex flex-wrap gap-2">
            {SUGGESTABLE_TLDS.map((t) => {
              const on = tlds.includes(t.tld);
              return (
                <button
                  key={t.tld}
                  type="button"
                  onClick={() => toggleTld(t.tld)}
                  title={t.note}
                  aria-pressed={on}
                  className={`rounded-lg border px-3 py-1.5 font-mono text-sm transition-colors ${
                    on
                      ? "border-brand-500/50 bg-brand-500/15 text-brand-200"
                      : "border-white/[0.08] bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-slate-200"
                  }`}
                >
                  {t.label}
                </button>
              );
            })}
          </div>
          <p className="mt-2 text-xs text-slate-500">
            We check your first extension across every name before spending checks on the next one.
          </p>
        </div>

        {!configured && (
          <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
            Live availability activates once the registrar integration is configured. You can still explore name
            ideas — each will be marked <b>couldn&apos;t verify</b> until then.
          </div>
        )}

        <div className="flex flex-wrap items-center gap-3">
          <button type="submit" className="btn-primary px-5 py-2.5" disabled={loading || idea.trim().length < 8}>
            {loading ? "Working…" : "Generate names"}
          </button>
          <span className="text-xs text-slate-500">Live availability from your registrar. Register straight from the results.</span>
        </div>
      </form>

      {error && (
        <div className="mt-5 rounded-xl border border-red-500/25 bg-red-500/10 px-4 py-3 text-sm text-red-300">{error}</div>
      )}

      {loading && (
        <div className="mt-6 rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
          <p className="flex items-center gap-2 text-sm text-slate-300">
            <span className="nx-skel h-2 w-2 rounded-full bg-brand-400" />
            {LOADING_STEPS[Math.min(step, LOADING_STEPS.length - 1)]}
          </p>
          <div className="mt-4 space-y-2">
            {Array.from({ length: 5 }).map((_, i) => (
              <div
                key={i}
                className="nx-skel h-11 rounded-xl border border-white/[0.05] bg-white/[0.03]"
                style={{ animationDelay: `${i * 120}ms` }}
              />
            ))}
          </div>
        </div>
      )}

      {data && !loading && (
        <div className="mt-6 space-y-6">
          {!data.registrarConfigured && (
            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
              <b>Live availability is temporarily unavailable.</b> These are still real name ideas — each is marked
              couldn&apos;t verify rather than shown as free.
            </div>
          )}
          {data.registrarConfigured && data.throttled && (
            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
              We&apos;re checking a lot of names right now, so some below weren&apos;t verified. Try again in a minute
              for the rest.
            </div>
          )}

          {available.length > 0 && (
            <section>
              <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
                <h3 className="text-base font-semibold text-white">
                  Available right now <span className="text-sm font-normal text-slate-500">({available.length})</span>
                </h3>
                <p className="text-xs text-slate-500">Price shown is the first year, from your registrar.</p>
              </div>
              <ul className="space-y-2">
                {available.map((r, i) => (
                  <li
                    key={r.domain}
                    className="nx-name-row rounded-xl border border-emerald-500/20 bg-emerald-500/[0.04] p-3 transition-colors hover:border-emerald-400/40 sm:p-4"
                    style={{ animationDelay: `${Math.min(i, 8) * 40}ms` }}
                  >
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                      <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400" />
                      <span className="min-w-0 break-all font-mono text-[15px] font-semibold text-white">
                        {r.domain}
                      </span>
                      {r.premium && (
                        <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
                          Premium
                        </span>
                      )}
                      <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-slate-400">
                        {STYLE_LABEL[r.style] ?? r.style}
                      </span>

                      <span className="ml-auto flex flex-wrap items-center gap-2 sm:gap-3">
                        {r.priceCents !== null && (
                          <span className="text-right text-sm">
                            <span className="font-semibold text-white">{fmtMoney(r.priceCents)}</span>
                            <span className="text-slate-500">/yr</span>
                          </span>
                        )}
                        <Link href={registerHref(r.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
                          Register →
                        </Link>
                      </span>
                    </div>
                    {(r.note || r.renewCents !== null) && (
                      <p className="mt-2 pl-5 text-xs leading-relaxed text-slate-500">
                        {r.note}
                        {r.note && r.renewCents !== null ? " · " : ""}
                        {r.renewCents !== null ? `Renews at ${fmtMoney(r.renewCents)}/yr` : ""}
                      </p>
                    )}
                  </li>
                ))}
              </ul>
              <p className="mt-3 text-xs leading-relaxed text-slate-500">
                Availability comes straight from your registrar and can change minute to minute. The register step
                re-checks the name and its exact price before it charges your wallet.
              </p>
            </section>
          )}

          {available.length === 0 && (
            <div className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-300">
              Every name we tried is already taken. That usually means the words are too obvious — try a more specific
              description, switch the style to <b>Invented &amp; brandable</b>, or add{" "}
              <span className="font-mono">.io</span> or <span className="font-mono">.co</span> to the extensions.
            </div>
          )}

          {unchecked.length > 0 && (
            <section>
              <h3 className="mb-3 text-base font-semibold text-white">
                Couldn&apos;t verify <span className="text-sm font-normal text-slate-500">({unchecked.length})</span>
              </h3>
              <ul className="flex flex-wrap gap-2">
                {unchecked.map((r) => (
                  <li
                    key={r.domain}
                    className="rounded-lg border border-white/[0.07] bg-navy-900/50 px-3 py-1.5 font-mono text-sm text-slate-300"
                  >
                    {r.domain}
                  </li>
                ))}
              </ul>
              <p className="mt-2 text-xs text-slate-500">
                We couldn&apos;t get an answer from the registrar for these. They may or may not be free — search them
                on the register page before committing.
              </p>
            </section>
          )}

          {taken.length > 0 && (
            <section>
              <h3 className="mb-3 text-base font-semibold text-slate-400">
                Already taken <span className="text-sm font-normal text-slate-600">({taken.length})</span>
              </h3>
              <ul className="flex flex-wrap gap-2">
                {taken.map((r) => (
                  <li
                    key={r.domain}
                    className="rounded-lg border border-white/[0.05] bg-white/[0.02] px-3 py-1.5 font-mono text-sm text-slate-600 line-through decoration-slate-700"
                  >
                    {r.domain}
                  </li>
                ))}
              </ul>
            </section>
          )}

          <div className="flex flex-wrap items-center gap-3 border-t border-white/[0.06] pt-4">
            <button type="button" className="btn-primary px-5 py-2.5" onClick={() => void run()} disabled={loading}>
              Generate another set
            </button>
            <Link href="/dashboard/domains/register" className="btn-secondary px-4 py-2 text-sm">
              Search an exact name
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

