import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  readString,
  readIdea,
  readTone,
  readTlds,
  mergeCandidates,
  buildDomains,
  toSuggestResult,
  isRegisterable,
  rankSuggestions,
  partitionResults,
  MAX_LOOKUPS,
  type SuggestResult,
} from "../lib/tools/domain-suggest.ts";
import { parseAiCandidates } from "../lib/tools/domain-ai.ts";
import type { Candidate } from "../lib/tools/domain-generate.ts";
import type { DomainResult } from "../lib/tools/domain-availability.ts";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const read = (rel: string) => readFileSync(path.join(HERE, "..", rel), "utf8");

const cand = (sld: string, style = "invented", note = ""): Candidate => ({ sld, style: style as Candidate["style"], note });
const avail = (domain: string, over: Partial<DomainResult> = {}): DomainResult => ({
  domain,
  status: "available",
  premium: false,
  priceCents: 1299,
  renewCents: 1499,
  ...over,
});
const result = (over: Partial<SuggestResult> = {}): SuggestResult => ({
  domain: "x.com",
  sld: "x",
  tld: "com",
  status: "available",
  premium: false,
  priceCents: 1299,
  renewCents: 1499,
  style: "invented",
  note: "",
  ...over,
});

// ───────────────────────────────────────────────────────────────────────────
// Input normalisation
// ───────────────────────────────────────────────────────────────────────────

test("readString collapses whitespace, trims, caps length, and rejects non-strings", () => {
  assert.equal(readString("  a   b\n c ", 100), "a b c");
  assert.equal(readString("abcdef", 3), "abc");
  assert.equal(readString(42, 100), "");
  assert.equal(readString(undefined, 100), "");
  assert.equal(readString(null, 100), "");
});

test("readIdea caps at the idea length limit", () => {
  const long = "a".repeat(500);
  assert.equal(readIdea(long).length, 400);
});

test("readTone accepts known tones and defaults everything else to 'any'", () => {
  assert.equal(readTone("playful"), "playful");
  assert.equal(readTone("professional"), "professional");
  assert.equal(readTone("nonsense"), "any");
  assert.equal(readTone(123), "any");
  assert.equal(readTone(""), "any");
});

test("readTlds sanitises: strips dots, lower-cases, dedupes, drops unknowns, caps at 3", () => {
  assert.deepEqual(readTlds([".COM", "io", "com", "io"]), ["com", "io"]);
  assert.deepEqual(readTlds(["com", "io", "dev", "app"]), ["com", "io", "dev"]); // capped at 3
  assert.deepEqual(readTlds(["not-a-tld", "zzz"]), ["com", "co"]); // falls back to defaults
  assert.deepEqual(readTlds("com"), ["com", "co"]); // non-array → defaults
  assert.deepEqual(readTlds([42, {}, "io"]), ["io"]); // non-strings skipped
});

test("readTlds returns a fresh array so a caller cannot mutate the shared default", () => {
  const a = readTlds("nope");
  a.push("hacked");
  assert.deepEqual(readTlds("nope"), ["com", "co"]);
});

// ───────────────────────────────────────────────────────────────────────────
// Candidate assembly
// ───────────────────────────────────────────────────────────────────────────

test("mergeCandidates fills a short AI list from the fallback, de-duplicating on label", () => {
  const ai = [cand("northbeam"), cand("saltmarket")];
  const fallback = [cand("saltmarket"), cand("verolo"), cand("cadenza")];
  const merged = mergeCandidates(ai, fallback, 4);
  assert.deepEqual(merged.map((c) => c.sld), ["northbeam", "saltmarket", "verolo", "cadenza"]);
});

test("mergeCandidates caps at max and keeps AI order first", () => {
  const ai = [cand("a"), cand("b"), cand("c")];
  const fallback = [cand("d"), cand("e")];
  assert.deepEqual(mergeCandidates(ai, fallback, 3).map((c) => c.sld), ["a", "b", "c"]);
});

test("mergeCandidates handles a null AI list (key absent / AI failed)", () => {
  const fallback = [cand("d"), cand("e"), cand("d")];
  assert.deepEqual(mergeCandidates(null, fallback, 5).map((c) => c.sld), ["d", "e"]);
});

// ───────────────────────────────────────────────────────────────────────────
// Domain pairing
// ───────────────────────────────────────────────────────────────────────────

test("buildDomains is TLD-major: every name on the first extension before the second", () => {
  const cs = [cand("alpha"), cand("beta")];
  assert.deepEqual(buildDomains(cs, ["com", "io"]), ["alpha.com", "beta.com", "alpha.io", "beta.io"]);
});

test("buildDomains never exceeds MAX_LOOKUPS", () => {
  const cs = Array.from({ length: 20 }, (_, i) => cand(`name${i}`));
  const domains = buildDomains(cs, ["com", "io", "co"]);
  assert.ok(domains.length <= MAX_LOOKUPS, `${domains.length} must be <= ${MAX_LOOKUPS}`);
});

// ───────────────────────────────────────────────────────────────────────────
// Result shaping + the honesty invariants
// ───────────────────────────────────────────────────────────────────────────

test("toSuggestResult splits sld/tld and carries the candidate's copy", () => {
  const r = toSuggestResult(avail("northbeam.com"), cand("northbeam", "compound", "Solid and structural."));
  assert.equal(r.sld, "northbeam");
  assert.equal(r.tld, "com");
  assert.equal(r.style, "compound");
  assert.equal(r.note, "Solid and structural.");
  assert.equal(r.status, "available");
  assert.equal(r.priceCents, 1299);
});

test("toSuggestResult defaults style/note when the candidate is unknown", () => {
  const r = toSuggestResult(avail("stray.com"), undefined);
  assert.equal(r.style, "invented");
  assert.equal(r.note, "");
});

test("an unverified name stays 'unknown' with no price — never promoted to available", () => {
  const r = toSuggestResult(
    { domain: "mystery.com", status: "unknown", premium: false, priceCents: null, renewCents: null },
    cand("mystery"),
  );
  assert.equal(r.status, "unknown");
  assert.equal(r.priceCents, null);
  assert.equal(isRegisterable(r), false, "we must not offer to register a name we couldn't verify");
});

test("isRegisterable requires BOTH availability and a real registrar price", () => {
  assert.equal(isRegisterable(result({ status: "available", priceCents: 1299 })), true);
  assert.equal(isRegisterable(result({ status: "available", priceCents: null })), false);
  assert.equal(isRegisterable(result({ status: "taken", priceCents: null })), false);
  assert.equal(isRegisterable(result({ status: "unknown", priceCents: null })), false);
});

// ───────────────────────────────────────────────────────────────────────────
// Ranking + the available-only partition
// ───────────────────────────────────────────────────────────────────────────

test("rankSuggestions puts available first (cheapest first), then unknown, then taken", () => {
  const rows = [
    result({ domain: "taken.com", status: "taken", priceCents: null }),
    result({ domain: "pricey.com", status: "available", priceCents: 3999 }),
    result({ domain: "cheap.com", status: "available", priceCents: 899 }),
    result({ domain: "maybe.com", status: "unknown", priceCents: null }),
  ];
  rankSuggestions(rows);
  assert.deepEqual(rows.map((r) => r.domain), ["cheap.com", "pricey.com", "maybe.com", "taken.com"]);
});

test("partitionResults isolates the available (differentiator) bucket from unknown and taken", () => {
  const rows = [
    result({ domain: "free.com", status: "available" }),
    result({ domain: "gone.com", status: "taken", priceCents: null }),
    result({ domain: "dunno.com", status: "unknown", priceCents: null }),
    result({ domain: "free2.io", status: "available" }),
  ];
  const { available, unchecked, taken } = partitionResults(rows);
  assert.deepEqual(available.map((r) => r.domain), ["free.com", "free2.io"]);
  assert.deepEqual(unchecked.map((r) => r.domain), ["dunno.com"]);
  assert.deepEqual(taken.map((r) => r.domain), ["gone.com"]);
  // Every name presented as "available" is genuinely registerable.
  assert.ok(available.every(isRegisterable), "the available bucket must contain only registerable names");
});

// ───────────────────────────────────────────────────────────────────────────
// AI suggestion parsing (the part most likely to drift with a model change)
// ───────────────────────────────────────────────────────────────────────────

test("parseAiCandidates reads a clean JSON array", () => {
  const text = '[{"name":"northbeam","style":"compound","why":"Solid."},{"name":"verolo","style":"invented","why":"Coined."}]';
  const out = parseAiCandidates(text, 12);
  assert.deepEqual(out.map((c) => c.sld), ["northbeam", "verolo"]);
  assert.equal(out[0].style, "compound");
  assert.equal(out[0].note, "Solid.");
});

test("parseAiCandidates tolerates prose and markdown fences around the array", () => {
  const text = 'Here are some ideas:\n```json\n[{"name":"cadenza"}]\n```\nHope that helps!';
  assert.deepEqual(parseAiCandidates(text, 12).map((c) => c.sld), ["cadenza"]);
});

test("parseAiCandidates drops rows whose name won't normalise, and de-duplicates", () => {
  const text = JSON.stringify([
    { name: "GoodName" },
    { name: "go" }, // too short after normalise → dropped
    { name: "has spaces and CAPS" }, // normalises to "hasspacesandcaps"
    { name: "goodname" }, // dup of first (case-insensitive)
    { name: "12345" }, // all digits → dropped
    { notName: "x" }, // no name → dropped
  ]);
  assert.deepEqual(parseAiCandidates(text, 12).map((c) => c.sld), ["goodname", "hasspacesandcaps"]);
});

test("parseAiCandidates respects the max and returns [] on unparseable input", () => {
  const many = JSON.stringify(Array.from({ length: 30 }, (_, i) => ({ name: `namealpha${i}` })));
  assert.equal(parseAiCandidates(many, 5).length, 5);
  assert.deepEqual(parseAiCandidates("not json at all", 12), []);
  assert.deepEqual(parseAiCandidates("", 12), []);
  assert.deepEqual(parseAiCandidates('{"name":"solo"}', 12), []); // an object, not an array
});

// ───────────────────────────────────────────────────────────────────────────
// Source tripwires — both surfaces must run through the ONE shared pipeline,
// and each must throttle on a key the caller cannot forge.
// ───────────────────────────────────────────────────────────────────────────

test("both generator routes call the shared generateSuggestions pipeline (no second copy)", () => {
  for (const route of [
    "app/api/tools/domain-generator/route.ts",
    "app/api/dashboard/domains/generate/route.ts",
  ]) {
    const src = stripCommentsAndStrings(read(route));
    assert.match(src, /generateSuggestions\s*\(/, `${route} must delegate to the shared pipeline`);
  }
});

test("the PUBLIC route throttles per proxy-attested IP and never re-derives one from XFF", () => {
  const src = stripCommentsAndStrings(read("app/api/tools/domain-generator/route.ts"));
  assert.match(src, /toolRateLimitByIp\s*\(/, "must use the shared IP limiter");
  assert.doesNotMatch(src, /split\(\s*","\s*\)\s*\[\s*0\s*\]/, "must not pick the spoofable first XFF hop");
  // Raw source: the file should not even mention the forgeable header.
  assert.doesNotMatch(read("app/api/tools/domain-generator/route.ts").toLowerCase(), /x-forwarded-for/);
});

test("the PORTAL route requires a session and throttles on the account, not the IP", () => {
  const raw = read("app/api/dashboard/domains/generate/route.ts");
  const shape = stripCommentsAndStrings(raw);
  assert.match(shape, /currentUser\s*\(/, "must resolve the signed-in user");
  assert.match(shape, /if\s*\(\s*!\s*user\s*\)/, "must reject unauthenticated callers");
  // Literal-preserving pass: the rate-limit key is the account id, not a header.
  assert.match(
    stripComments(raw),
    /checkRateLimit\(\s*`tool:domain-generator[^`]*:user:\$\{user\.id\}/,
    "the throttle must key on the un-forgeable account id",
  );
});

test("the portal generator UI only offers Register on a name it can price", () => {
  // The component derives its 'available' bucket by availability status, and the
  // Register link/price live in that bucket. Guard the status literal so a later
  // edit can't quietly start rendering Register on taken/unknown names.
